actions.code:
type TooltipRootActions = {
    unmount: () => void;
    close: () => void;
};

changeEventDetails.code:
type TooltipRootChangeEventDetails = ({
    reason: 'trigger-hover';
    event: MouseEvent;
} | {
    reason: 'trigger-focus';
    event: FocusEvent;
} | {
    reason: 'trigger-press';
    event: MouseEvent | PointerEvent | TouchEvent | KeyboardEvent;
} | {
    reason: 'outside-press';
    event: MouseEvent | PointerEvent | TouchEvent;
} | {
    reason: 'escape-key';
    event: KeyboardEvent;
} | {
    reason: 'disabled';
    event: Event;
} | {
    reason: 'imperative-action';
    event: Event;
} | {
    reason: 'none';
    event: Event;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
    preventUnmountOnClose: () => void;
};

state.code:
type TooltipPositionerState = {
    open: boolean;
    side: Side;
    align: Align;
    anchorHidden: boolean;
    instant: string | undefined;
};

type TooltipPopupState = {
    open: boolean;
    side: Side;
    align: Align;
    instant: 'delay' | 'focus' | 'dismiss' | undefined;
    transitionStatus: TransitionStatus;
};

type TooltipArrowState = {
    open: boolean;
    side: Side;
    align: Align;
    uncentered: boolean;
    instant: 'delay' | 'dismiss' | 'focus' | undefined;
};

type TooltipViewportState = {
    activationDirection: string | undefined;
    transitioning: boolean;
    instant: 'delay' | 'dismiss' | 'focus' | undefined;
};

